(() => {
 const dialog=document.createElement('dialog');dialog.className='settings-dialog';dialog.innerHTML=`<div class="help-head"><h2>设置 · MCP 地图与素材生成</h2><button id="closeSettings">关闭</button></div><p>将下面的配置添加到 AI 客户端的 MCP 设置。AI 通过工具生成素材或组建地图；浏览器通过本地服务接收结果。</p><label>MCP 配置（JSON）<textarea id="mcpConfig" spellcheck="false"></textarea></label><button id="saveMcp">保存配置</button> <button id="copyMcp">复制配置</button><p id="mcpStatus">尚未连接</p><label>编辑器服务地址<input id="mcpUrl" value="http://127.0.0.1:8765" style="width:100%"></label><button id="connectMcp">连接 / 检测</button><p>浏览器无法启动 stdio 进程。请在配置中把路径改为本机的绝对路径，然后由 AI 客户端启动该 MCP；也可在仓库运行 <code>node 编辑器/mcp-server.cjs --serve</code>，从服务地址打开编辑器。</p><h3>AI 必须遵循的流程</h3><ol><li>read_guidance：读取全部分类指导，取得 guidanceToken。</li><li>list_assets：查看已有素材、真实工厂和风格。</li><li>create_asset：提交带材质槽、碰撞和风格参考的 HTML。</li><li>validate_map / create_map：晴天、可行走底板、双方安全出生点、四边封闭空气墙；验证失败必须修正。</li></ol><p>通过服务生成的地图先显示“载入”按钮，由你选择何时载入，避免覆盖正在搭建的内容。</p><div id="mcpResults"></div>`;document.body.append(dialog);
 const $=id=>document.getElementById(id),config={mcpServers:{'along-map-editor':{command:'node',args:['F:/AAAtask/fps/编辑器/mcp-server.cjs']}}};
 try{$('mcpConfig').value=localStorage.getItem('along.mcp.config')||JSON.stringify(config,null,2);$('mcpUrl').value=localStorage.getItem('along.mcp.url')||location.origin;}catch{$('mcpConfig').value=JSON.stringify(config,null,2);}
 $('settingsButton').onclick=()=>dialog.showModal();$('closeSettings').onclick=()=>dialog.close();$('saveMcp').onclick=()=>{try{const value=JSON.parse($('mcpConfig').value);if(!value.mcpServers||typeof value.mcpServers!=='object')throw Error('需要 mcpServers 对象');localStorage.setItem('along.mcp.config',JSON.stringify(value,null,2));$('mcpStatus').textContent='配置已保存在此浏览器，请粘贴到 AI 客户端 MCP 设置后启动';}catch(e){$('mcpStatus').textContent='配置错误：'+e.message;}};$('copyMcp').onclick=async()=>{try{JSON.parse($('mcpConfig').value);await navigator.clipboard.writeText($('mcpConfig').value);$('mcpStatus').textContent='配置已复制';}catch(e){$('mcpStatus').textContent='复制失败，请手动复制：'+e.message;}};
 let revision=0,connected=false,pending=false;
 async function poll(){if(!connected||pending)return;pending=true;try{const base=new URL($('mcpUrl').value);if(base.origin!==location.origin)throw Error('请从 '+base.origin+'/编辑器/index.html 打开编辑器以连接服务');const r=await fetch('/api/events?after='+revision);if(!r.ok)throw Error('服务不可用');for(const event of await r.json()){revision=Math.max(revision,event.revision);if(event.type==='asset')window.alongEditor?.importAsset(event.asset);if(event.type==='map'){const button=document.createElement('button');button.textContent='载入生成地图：'+event.project.name;button.onclick=()=>{if(window.alongEditor.snapshot().objects.length&&!confirm('载入将替换当前场景，请先保存工程。继续？'))return;window.alongEditor.restore(event.project);dialog.close();};$('mcpResults').append(button);$('mcpStatus').textContent='收到生成地图：'+event.project.name;}}}catch(e){$('mcpStatus').textContent=e.message;connected=false;}finally{pending=false;}}
 $('connectMcp').onclick=async()=>{try{const base=new URL($('mcpUrl').value);if(!['127.0.0.1','localhost'].includes(base.hostname))throw Error('仅支持本机服务');if(base.origin!==location.origin)throw Error('请从 '+base.origin+'/编辑器/index.html 打开编辑器');const r=await fetch('/api/status');if(!r.ok)throw Error('未检测到服务');const status=await r.json();if(status.name!=='along-map-editor')throw Error('不是沿线 MCP 服务');connected=true;localStorage.setItem('along.mcp.url',base.origin);$('mcpStatus').textContent='已连接 '+status.name;await poll();}catch(e){$('mcpStatus').textContent=e.message;}};
 setInterval(poll,1800);
 if(/^https?:$/.test(location.protocol))$('connectMcp').click();
})();
